values = [1, [2, [3]], 4]
stack = list(reversed(values))
result = []
while stack:
    value = stack.pop()
    if isinstance(value, list):
        stack.extend(reversed(value))
    else:
        result.append(value)
print(result)

from queue import Queue, Empty, Full
queue = Queue(maxsize=1)
queue.put_nowait("A")
try:
    queue.put_nowait("B")
except Full:
    print("full")
print(queue.get_nowait())
queue.task_done()
try:
    queue.get_nowait()
except Empty:
    print("empty")

